84	 * Migrates a v3 save to v4 — a pure version bump. `blockEntities` (chest
85	 * contents) is optional, so a pre-chest save simply loads with no containers.
86	 */
87	export function migrateSaveV3toV4(save: SaveDataV3): SaveDataV4 {
88	  return { ...save, version: 4 };
