126	/**
127	 * Migrates a v8 save to v9 — a pure version bump. `difficulty` is optional, so a
128	 * pre-difficulty save simply loads as "normal" (see restoreDifficulty).
129	 */
130	export function migrateSaveV8toV9(save: SaveDataV8): SaveDataV9 {
131	  return { ...save, version: 9 };
132	}
133	
134	/**
135	 * Migrates a v9 save to v10 — a pure version bump. `hardcore`/`gameOver` are
136	 * optional, so a pre-Hardcore save simply loads as a normal, non-hardcore world
137	 * (see restoreHardcore/restoreGameOver).
138	 */
139	export function migrateSaveV9toV10(save: SaveDataV9): SaveDataV10 {
140	  return { ...save, version: 10 };
141	}
142	
143	/**
144	 * Migrates a v10 save to v11. v11 adds an optional per-item `customName` (the
145	 * anvil rename) inside each `SavedSlot`; the Mending enchantment rides the
146	 * existing per-slot `enchantments`. Both are additive, so this is a pure version
147	 * bump and pre-v11 saves load with no custom names.
148	 */
149	export function migrateSaveV10toV11(save: SaveDataV10): SaveDataV11 {
150	  return { ...save, version: 11 };
151	}
152	
153	/**
154	 * Migrates a v11 save to v12 — armor moves to dedicated storage. The legacy
155	 * `equippedArmor` was a by-id reference into `inventorySlots` (the worn item also
156	 * lived in the inventory). For each valid equip, move the matching inventory item
157	 * out into the armor record (preserving durability/enchantments/customName); drop
158	 * equips whose item isn't found or isn't valid armor for the slot. Pre-`inventorySlots`
159	 * (legacy counts-only) saves simply drop the equip map and keep items in inventory.
160	 */
161	export function migrateSaveV11toV12(save: SaveDataV11): SaveDataV12 {
162	  const legacy = save.equippedArmor;
163	  if (!legacy || !Array.isArray(save.inventorySlots)) {
164	    return { ...save, version: 12, equippedArmor: undefined };
165	  }
166	  const slots = save.inventorySlots.slice();
167	  const equipped: SavedEquippedArmor = {};
168	  for (const armorSlot of ARMOR_SLOTS) {
169	    const id = legacy[armorSlot];
170	    if (!id) continue;
171	    const def = ITEM_DEF_BY_ID[id];
172	    if (def?.kind !== "armor" || def.armorSlot !== armorSlot) continue; // drop invalid equips
173	    const idx = slots.findIndex((s) => s?.id === id && s.count > 0);
174	    if (idx < 0) continue; // item not in inventory → drop the equip
175	    equipped[armorSlot] = slots[idx]; // preserves durability/enchantments/customName
176	    slots[idx] = { id: null, count: 0 };
177	  }
178	  return { ...save, version: 12, inventorySlots: slots, equippedArmor: equipped };
179	}
180	
181	/**
182	 * Migrates a v12 save to v13 — a pure version bump. `stats` (gameplay counters)
183	 * and `advancements` (unlocked ids) are optional, so a pre-progression save
184	 * simply loads with no stats and no advancements yet earned.
185	 */
186	export function migrateSaveV12toV13(save: SaveDataV12): SaveData {
187	  return { ...save, version: 13 };
188	}
189	
190	// Storage is injectable so save logic can be tested without a browser.
191	export function readSave(saveKey: string, storage: Storage = localStorage): SaveData | null {
192	  try {
193	    const raw = storage.getItem(saveKey);
194	    if (!raw) return null;
195	    const parsed = JSON.parse(raw) as
196	      | SaveData
197	      | SaveDataV12
198	      | SaveDataV11
199	      | SaveDataV10
200	      | SaveDataV9
201	      | SaveDataV8
202	      | SaveDataV7
203	      | SaveDataV6
204	      | SaveDataV5
205	      | SaveDataV4
206	      | SaveDataV3
207	      | SaveDataV2
208	      | SaveDataV1;
209	    if (!parsed || !Number.isFinite(parsed.seed) || !Array.isArray(parsed.changes)) return null;
210	    let migrated:
211	      | SaveDataV2
212	      | SaveDataV3
213	      | SaveDataV4
214	      | SaveDataV5
215	      | SaveDataV6
216	      | SaveDataV7
217	      | SaveDataV8
218	      | SaveDataV9
219	      | SaveDataV10
220	      | SaveDataV11
221	      | SaveDataV12
222	      | SaveData = parsed.version === 1 ? migrateSaveV1toV2(parsed) : parsed;
223	    if (migrated.version === 2) migrated = migrateSaveV2toV3(migrated);
224	    if (migrated.version === 3) migrated = migrateSaveV3toV4(migrated);
225	    if (migrated.version === 4) migrated = migrateSaveV4toV5(migrated);
226	    if (migrated.version === 5) migrated = migrateSaveV5toV6(migrated);
227	    if (migrated.version === 6) migrated = migrateSaveV6toV7(migrated);
228	    if (migrated.version === 7) migrated = migrateSaveV7toV8(migrated);
229	    if (migrated.version === 8) migrated = migrateSaveV8toV9(migrated);
230	    if (migrated.version === 9) migrated = migrateSaveV9toV10(migrated);
231	    if (migrated.version === 10) migrated = migrateSaveV10toV11(migrated);
232	    if (migrated.version === 11) migrated = migrateSaveV11toV12(migrated);
233	    if (migrated.version === 12) migrated = migrateSaveV12toV13(migrated);
234	    if (migrated.version !== 13) return null;
235	    return migrated;
236	  } catch {
237	    return null;
238	  }
239	}
240	
241	export function writeSave(saveKey: string, data: SaveData, storage: Storage = localStorage): void {
242	  storage.setItem(saveKey, JSON.stringify(data));
243	}
244	
245	export function inventorySlotsSnapshot(inventory: InventorySlot[]): SavedSlot[] {
246	  return inventory.map((slot) => ({
247	    id: slot.id,
248	    count: slot.count,
249	    durability: slot.durability,
250	    enchantments: slot.enchantments,
251	    customName: slot.customName
252	  }));
253	}
254	
255	/** Snapshots the worn armor pieces for persistence (sparse — empty slots are omitted). */
256	export function serializeEquippedArmor(equipped: EquippedArmor): SavedEquippedArmor {
257	  const out: SavedEquippedArmor = {};
258	  for (const armorSlot of ARMOR_SLOTS) {
259	    const piece = equipped[armorSlot];
260	    if (!piece?.id || piece.count <= 0) continue;
261	    out[armorSlot] = { id: piece.id, count: piece.count, durability: piece.durability, enchantments: piece.enchantments, customName: piece.customName };
262	  }
263	  return out;
264	}
265	
266	// Every known enchantment id, keyed so a new enchantment can't be forgotten here.
267	const VALID_ENCHANT_IDS: Record<EnchantmentId, true> = {
268	  sharpness: true,
269	  protection: true,
270	  efficiency: true,
271	  unbreaking: true,
272	  mending: true,
273	  power: true,
274	  punch: true,
275	  knockback: true,
276	  looting: true,
277	  fortune: true,
278	  feather_falling: true
279	};
280	
281	/** Validates persisted enchantments: known ids and integer levels clamped to 1..(that enchant's max); undefined when none survive. */
282	function restoreEnchantments(saved: SavedSlot["enchantments"]): Enchantment[] | undefined {
283	  if (!Array.isArray(saved)) return undefined;
284	  const out: Enchantment[] = [];
285	  for (const entry of saved) {
286	    if (!entry || typeof entry.id !== "string" || !Object.hasOwn(VALID_ENCHANT_IDS, entry.id)) continue;
287	    if (!Number.isFinite(entry.level) || Math.floor(entry.level) < 1) continue;
288	    // Clamp to the enchantment's own cap so e.g. a tampered mending:3 loads as 1.
289	    out.push({ id: entry.id, level: Math.min(ENCHANTMENT_DEFS[entry.id].maxLevel, Math.floor(entry.level)) });
290	  }
291	  return out.length > 0 ? out : undefined;
292	}
293	
294	/**
295	 * Rebuilds one slot from its saved snapshot: drops unknown ids, clamps the
296	 * count, and clamps/defaults durability for gear (a non-positive saved
297	 * durability means the piece broke and is dropped). Returns an empty slot for
298	 * anything invalid. Shared by inventory and container restore.
299	 */
300	function restoreSlot(saved: SavedSlot | undefined): InventorySlot {
301	  if (!saved?.id || saved.count <= 0 || !ITEM_DEF_BY_ID[saved.id]) return createEmptySlot();
302	  const slot = createSlot(saved.id, Math.min(maxStackSizeForItem(saved.id), Math.max(0, Math.floor(saved.count))));
303	  if ((slot.kind === "tool" || slot.kind === "weapon" || slot.kind === "armor") && slot.maxDurability) {
304	    if (typeof saved.durability === "number") {
305	      const loaded = Math.floor(saved.durability);
306	      if (loaded <= 0) return createEmptySlot();
307	      slot.durability = Math.max(1, Math.min(slot.maxDurability, loaded));
308	    } else {
309	      slot.durability = slot.maxDurability;
310	    }
311	    // Enchantments live only on durable gear; validated against the known set.
312	    const enchantments = restoreEnchantments(saved.enchantments);
313	    if (enchantments) slot.enchantments = enchantments;
314	    // A custom name (anvil rename) also lives only on durable gear; trim and cap it.
315	    if (typeof saved.customName === "string") {
316	      const name = saved.customName.trim().slice(0, CUSTOM_NAME_MAX_LEN);
317	      if (name) slot.customName = name;
318	    }
319	  }
320	  return slot;
321	}
322	
323	/** Snapshots non-empty chest containers for persistence (empty chests carry no data). */
324	export function serializeContainers(containers: Map<number, InventorySlot[]>): SavedContainer[] {
325	  const out: SavedContainer[] = [];
326	  for (const [index, slots] of containers) {
327	    if (!slots.some((slot) => slot.id && slot.count > 0)) continue;
328	    out.push({ index, slots: inventorySlotsSnapshot(slots) });
329	  }
330	  return out;
331	}
332	
333	/** Snapshots the set of opened/broken dungeon chest voxel indices for persistence. */
334	export function serializeLootedChests(looted: Set<number>): number[] {
335	  return [...looted];
336	}
337	
338	/** Reads the opened/broken dungeon chest indices from a save (finite numbers only). */
339	export function readLootedChests(save: SaveData): number[] {
340	  if (!Array.isArray(save.lootedChests)) return [];
341	  return save.lootedChests.filter((value) => Number.isFinite(value));
342	}
343	
344	// Every known status-effect id, as a Record keyed by EffectId so adding an
345	// effect without listing it here is a compile error (keeps the reader total).
346	const VALID_EFFECT_IDS: Record<EffectId, true> = {
347	  speed: true,
348	  strength: true,
349	  regeneration: true,
350	  fire_resistance: true,
351	  water_breathing: true,
352	  haste: true,
353	  resistance: true,
354	  jump_boost: true,
355	  poison: true
356	};
357	
358	/** Snapshots the active status effects (id + remaining seconds) for persistence. */
359	export function serializeEffects(effects: Map<EffectId, number>): SavedEffect[] {
360	  const out: SavedEffect[] = [];
361	  for (const [id, remaining] of effects) {
362	    if (remaining > 0) out.push({ id, remaining });
363	  }
364	  return out;
365	}
366	
367	/** Reads active effects from a save, dropping unknown ids and non-positive/garbage durations. */
368	export function restoreEffects(save: SaveData): SavedEffect[] {
369	  if (!Array.isArray(save.effects)) return [];
370	  const out: SavedEffect[] = [];
371	  for (const entry of save.effects) {
372	    if (!entry || typeof entry.id !== "string" || !Object.hasOwn(VALID_EFFECT_IDS, entry.id)) continue;
373	    if (!Number.isFinite(entry.remaining) || entry.remaining <= 0) continue;
374	    out.push({ id: entry.id, remaining: entry.remaining });
375	  }
376	  return out;
377	}
378	
379	/**
380	 * Snapshots the gameplay statistics for persistence. Zero/absent counters carry
381	 * no data (an unset stat reads as 0 anyway), so only positive values are written.
382	 * Unlike effect ids, stat ids are an open set (per-recipe/per-block counters), so
383	 * there's no allow-list — only a finite, positive-value check.
384	 */
385	export function serializeStats(stats: Map<string, number>): SavedStat[] {
386	  const out: SavedStat[] = [];
387	  for (const [id, value] of stats) {
388	    if (Number.isFinite(value) && value > 0) out.push({ id, value });
389	  }
390	  return out;
391	}
392	
393	/** Reads gameplay statistics from a save, dropping non-string ids and negative / garbage values. */
394	export function restoreStats(save: SaveData): SavedStat[] {
395	  if (!Array.isArray(save.stats)) return [];
396	  const out: SavedStat[] = [];
397	  for (const entry of save.stats) {
398	    if (!entry || typeof entry.id !== "string") continue;
399	    if (!Number.isFinite(entry.value) || entry.value < 0) continue;
400	    out.push({ id: entry.id, value: entry.value });
401	  }
402	  return out;
403	}
404	
405	/** Reads the unlocked advancement ids from a save (non-empty strings only, de-duplicated). */
406	export function restoreAdvancements(save: SaveData): string[] {
407	  if (!Array.isArray(save.advancements)) return [];
408	  const seen = new Set<string>();
409	  for (const id of save.advancements) {
410	    if (typeof id === "string" && id) seen.add(id);
411	  }
412	  return [...seen];
413	}
414	
415	/**
416	 * Reads chest containers from a save into validated, CHEST_SLOTS-length slot
417	 * arrays keyed by voxel index. Per-slot validation only — the engine still
418	 * confirms each index actually holds a Chest block before using it.
419	 */
420	export function readContainers(save: SaveData): Array<{ index: number; slots: InventorySlot[] }> {
421	  if (!Array.isArray(save.blockEntities)) return [];
422	  const out: Array<{ index: number; slots: InventorySlot[] }> = [];
423	  for (const entry of save.blockEntities) {
424	    if (!entry || !Number.isFinite(entry.index) || !Array.isArray(entry.slots)) continue;
425	    const slots = Array.from({ length: CHEST_SLOTS }, (_, i) => restoreSlot(entry.slots[i]));
426	    out.push({ index: entry.index, slots });
427	  }
428	  return out;
429	}
430	
431	/**
432	 * Rebuilds inventory slots from a save, dropping unknown items, clamping
433	 * counts and durability, and skipping broken gear. Supports both the current
434	 * inventorySlots shape and the legacy inventoryCounts shape. Returns null when
435	 * the save carries no inventory.
436	 */
437	export function restoreInventorySlots(save: SaveData): InventorySlot[] | null {
438	  if (Array.isArray(save.inventorySlots)) {
439	    const slots = Array.from({ length: INVENTORY_SLOTS }, () => createEmptySlot());
440	    for (let i = 0; i < Math.min(INVENTORY_SLOTS, save.inventorySlots.length); i += 1) {
441	      slots[i] = restoreSlot(save.inventorySlots[i]);
442	    }
443	    return slots;
444	  }
445	
446	  if (save.inventoryCounts) {
447	    const slots = Array.from({ length: INVENTORY_SLOTS }, () => createEmptySlot());
448	    let cursor = 0;
449	    for (const [id, raw] of Object.entries(save.inventoryCounts)) {
450	      if (!ITEM_DEF_BY_ID[id]) continue;
451	      let remaining = Math.max(0, Math.floor(raw));
452	      while (remaining > 0 && cursor < slots.length) {
453	        const add = Math.min(maxStackSizeForItem(id), remaining);
454	        slots[cursor] = createSlot(id, add);
455	        cursor += 1;
456	        remaining -= add;
457	      }
458	    }
459	    return slots;
460	  }
461	
462	  return null;
463	}
464	
465	/** Restores worn armor, rebuilding each piece through restoreSlot and dropping anything that isn't valid armor for its slot. */
466	export function restoreEquippedArmor(save: SaveData): EquippedArmor | null {
467	  if (!save.equippedArmor) return null;
468	  const next = createEmptyArmorEquipment();
469	  for (const armorSlot of ARMOR_SLOTS) {
470	    const saved = save.equippedArmor[armorSlot];
471	    if (!saved) continue;
472	    const slot = restoreSlot(saved);
473	    if (slot.kind !== "armor" || slot.armorSlot !== armorSlot || slot.count <= 0) continue;
474	    next[armorSlot] = slot;
475	  }
476	  return next;
477	}
478	
479	export function restoreSelectedSlot(save: SaveData): number | null {
480	  if (typeof save.selectedSlot !== "number") return null;
481	  return normalizeSelectedSlot(save.selectedSlot);
482	}
483	
484	/** Restores the day clock from a save (finite, non-negative); null if absent/invalid. */
485	export function restoreDayClock(save: SaveData): number | null {
486	  if (typeof save.dayClock !== "number" || !Number.isFinite(save.dayClock) || save.dayClock < 0) return null;
487	  return save.dayClock;
488	}
489	
490	/** Restores hearts clamped to 1..MAX_HEARTS; null if absent/invalid. */
491	export function restoreHearts(save: SaveData): number | null {
492	  if (typeof save.hearts !== "number" || !Number.isFinite(save.hearts)) return null;
493	  return Math.max(1, Math.min(MAX_HEARTS, Math.floor(save.hearts)));
494	}
495	
496	/** Restores hunger clamped to 0..MAX_HUNGER; null if absent/invalid. */
497	export function restoreHungerLevel(save: SaveData): number | null {
498	  if (typeof save.hunger !== "number" || !Number.isFinite(save.hunger)) return null;
499	  return Math.max(0, Math.min(MAX_HUNGER, Math.floor(save.hunger)));
500	}
501	
502	/** Restores banked XP (finite, ≥ 0); 0 when absent or invalid. */
503	export function restoreXp(save: SaveData): number {
504	  if (typeof save.xp !== "number" || !Number.isFinite(save.xp) || save.xp < 0) return 0;
505	  return Math.floor(save.xp);
506	}
507	
508	/** Restores the saved game mode; "survival" when absent or invalid (pre-v8 saves). */
509	export function restoreGameMode(save: SaveData): GameMode {
510	  return isGameMode(save.gameMode) ? save.gameMode : "survival";
511	}
512	
513	/** Restores the saved difficulty; "normal" when absent or invalid (pre-v9 saves). */
514	export function restoreDifficulty(save: SaveData): Difficulty {
515	  return isDifficulty(save.difficulty) ? save.difficulty : "normal";
516	}
517	
518	/** Restores the Hardcore flag; false when absent or non-boolean (pre-v10 saves). */
519	export function restoreHardcore(save: SaveData): boolean {
520	  return save.hardcore === true;
521	}
522	
523	/** Restores the permadeath game-over flag — only ever true on a hardcore save, so a stray flag on a non-hardcore (corrupt) save can't lock it into spectator. */
524	export function restoreGameOver(save: SaveData): boolean {
525	  return save.hardcore === true && save.gameOver === true;
526	}
527	
528	/** Restores the bed respawn point; null if absent or explicitly cleared. */
529	export function restoreSpawnPoint(save: SaveData): { x: number; y: number; z: number } | null {
530	  const sp = save.spawnPoint;
531	  if (!sp || !Number.isFinite(sp.x) || !Number.isFinite(sp.y) || !Number.isFinite(sp.z)) return null;
532	  return { x: Math.floor(sp.x), y: Math.floor(sp.y), z: Math.floor(sp.z) };
533	}
534	
535	/**
536	 * Restores the player's position; null when absent or non-finite. A corrupt save
537	 * with NaN/Infinity coords would otherwise load a broken world — and slip past the
538	 * `position.y < 2` unstuck net, since any comparison with NaN is false. Coords stay
539	 * floats (the player isn't grid-aligned), unlike the floored spawn point.
540	 */
541	export function restorePlayerPosition(save: SaveData): { x: number; y: number; z: number } | null {
542	  const p = save.player;
543	  if (!p || !Number.isFinite(p.x) || !Number.isFinite(p.y) || !Number.isFinite(p.z)) return null;
544	  return { x: p.x, y: p.y, z: p.z };
545	}
